"""Generate or check the synthetic models/evidence reference and schemas."""
from __future__ import annotations
import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from app.application.models import CONTRACTS, SCHEMA_VERSION


def render():
    md = [
        "---", "title: Models and evidence contracts (generated)", "tags: [currentcraft, generated]", "---", "",
        "# Models and evidence contracts (generated)", "",
        "Generated by `scripts/gen_models_contract_docs.py`. Never edit by hand.", "",
        f"Schema version: `{SCHEMA_VERSION}`.",
        "Design: [Synthetic models and evidence](../pipelines/MODELS_EVIDENCE.md).", "",
        "Synthetic capture and declarations only. Structural validation does not establish",
        "source authenticity, sanitization, split independence, authorization or training rights.", "",
    ]
    files = {}
    for model in CONTRACTS:
        md += [f"## `{model.__name__}`", "", model.__doc__ or "", "",
               "| Field | Required | Description |", "| --- | --- | --- |"]
        for name, field in model.model_fields.items():
            if not field.description:
                raise ValueError("field description missing")
            md.append(f"| `{name}` | {'yes' if field.is_required() else 'no'} | {field.description} |")
        rel = f"schemas/models/{model.__name__}.schema.json"
        md += ["", f"[JSON Schema]({rel})", ""]
        files[rel] = json.dumps(model.model_json_schema(), sort_keys=True, separators=(",", ":")) + "\n"
    files["MODELS_EVIDENCE_CONTRACTS.md"] = "\n".join(md)
    return files


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--check", action="store_true")
    args = p.parse_args()
    root = ROOT / "docs/contracts"
    files = render()
    stale = []
    for rel, text in files.items():
        target = root / rel
        if args.check:
            if not target.exists() or target.read_text() != text:
                stale.append(rel)
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text)
    extra = []
    if args.check:
        extra = [str(x.relative_to(root)) for x in (root / "schemas/models").glob("*.json")
                 if str(x.relative_to(root)) not in files]
    for rel in stale:
        print("STALE " + rel)
    for rel in extra:
        print("ORPHAN " + rel)
    print(f"{len(files)} generated artifacts; {len(stale)} stale; {len(extra)} orphan")
    return int(bool(stale or extra))


if __name__ == "__main__":
    raise SystemExit(main())
